mapper.select:
select region_id as segmId, super_region_id as parentSegmId, region_name as segmName, region_name as standName, region_no as segmNo, notes as notes from spc_region
and ifnull(delete_state, '0') = '0'
and region_id = #{bo.segmId}
and super_region_id = #{bo.parentSegmId}
and region_name like concat('%', #{bo.segmName}, '%')
order by region_no
